mapper.insert:
	/* fileProcDao1010 : 파일 등록 처리 */
	INSERT INTO FILE_INFO
    (
        	FILE_ID
        , 	FILE_SNO
        , 	FILE_NM
        , 	SAVE_FILE_NM
        , 	FILETYPE_CD
        , 	FILE_PATH
        , 	FILE_EXT
        , 	FILE_SIZE
        , 	REG_IDX
        , 	REG_DT
        , 	USE_YN
        , 	DISP_ORDER
        , 	REMARK
    )
    VALUES
    (
        	#{fileId, jdbcType=VARCHAR}
        , 	(SELECT LPAD(NVL(MAX(TO_NUMBER(FILE_SNO)), 0) + 1, 4, '0') FROM FILE_INFO WHERE FILE_ID = #{fileId, jdbcType=VARCHAR})
        , 	#{fileNm, jdbcType=VARCHAR}
        , 	#{saveFileNm, jdbcType=VARCHAR}
        , 	#{filetypeCd, jdbcType=VARCHAR}
        , 	#{filePath, jdbcType=VARCHAR}
        , 	#{fileExt, jdbcType=VARCHAR}
        , 	#{fileSize, jdbcType=NUMERIC}
        , 	#{regIdx, jdbcType=VARCHAR}
        , 	SYSDATE
        , 	'Y'
        , 	(SELECT NVL(MAX(DISP_ORDER), 0) + 1 FROM FILE_INFO WHERE FILE_ID = #{fileId, jdbcType=VARCHAR})
        , 	NULL
    )

mapper.update:
/* fileProcDao1020 : 파일 삭제 처리 (수정) */
UPDATE FILE_INFO
	SET USE_YN = 'N'
		, MOD_IDX = #{modIdx, jdbcType=VARCHAR}
		, MOD_DT = SYSDATE
WHERE FILE_ID = #{fileId, jdbcType=VARCHAR}

		AND FILE_SNO = #{fileSno, jdbcType=VARCHAR}

mapper.delete:
/* fileProcDao1030 : 파일 삭제 처리 (삭제) */
DELETE FILE_INFO
WHERE FILE_ID = #{fileId, jdbcType=VARCHAR}

		AND FILE_SNO = #{fileSno, jdbcType=VARCHAR}
